solution.solution.c:
#include <stddef.h>
#include <string.h>

/* Used by the tests: leave these as they are. */
struct pt { double x, y; };
static int is_even(const void *p) { return *(const int *)p % 2 == 0; }
static int above(const void *p) { return ((const struct pt *)p)->y > 0; }

void reverse_any(void *base, size_t n, size_t size)
{
    unsigned char *b = base;
    unsigned char tmp[256];
    if (size > sizeof tmp || n < 2) return;
    for (size_t i = 0, j = n - 1; i < j; i++, j--) {
        memcpy(tmp, b + i * size, size);
        memcpy(b + i * size, b + j * size, size);
        memcpy(b + j * size, tmp, size);
    }
}

size_t count_if(const void *base, size_t n, size_t size, int (*pred)(const void *item))
{
    const unsigned char *b = base;
    size_t count = 0;
    for (size_t i = 0; i < n; i++)
        if (pred(b + i * size)) count++;
    return count;
}

unitTests:
TEST("reverse ints") { int a[] = {1, 2, 3, 4, 5}; reverse_any(a, 5, sizeof a[0]); CHECK_EQ(a[0], 5); CHECK_EQ(a[2], 3); CHECK_EQ(a[4], 1); }
TEST("reverse structs and doubles") { struct pt p[] = {{1, 2}, {3, -4}}; reverse_any(p, 2, sizeof p[0]); CHECK_NEAR(p[0].x, 3.0, 1e-9); CHECK_NEAR(p[1].y, 2.0, 1e-9); double d[] = {1.5, 2.5, 3.5, 4.5}; reverse_any(d, 4, sizeof d[0]); CHECK_NEAR(d[0], 4.5, 1e-9); CHECK_NEAR(d[3], 1.5, 1e-9); }
TEST("tiny arrays") { int one[] = {7}; reverse_any(one, 1, sizeof one[0]); CHECK_EQ(one[0], 7); reverse_any(NULL, 0, sizeof(int)); }
TEST("count_if") { int a[] = {1, 2, 3, 4, 6}; CHECK_EQ((int)count_if(a, 5, sizeof a[0], is_even), 3); struct pt p[] = {{0, 1}, {0, -1}, {0, 5}}; CHECK_EQ((int)count_if(p, 3, sizeof p[0], above), 2); CHECK_EQ((int)count_if(a, 0, sizeof a[0], is_even), 0); }

